+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days, actual use from every "consume" movement, and the
+ * difference (actual minus theoretical), 3 decimals.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (at) => {
+    const day = at.slice(0, 10);
+    return day >= from && day <= to;
+  };
+  const lines = new Map();
+  const line = (itemId) => {
+    if (!lines.has(itemId)) lines.set(itemId, { theoretical: 0, actual: 0 });
+    return lines.get(itemId);
+  };
+  for (const sale of store.data.sales ?? [])
+    for (const l of sale.lines) if (inRange(l.soldAt)) for (const u of l.uses) line(u.itemId).theoretical += u.qty;
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) line(batch.itemId).actual += m.qty;
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return [...lines]
+    .map(([itemId, l]) => ({ itemId, theoretical: r3(l.theoretical), actual: r3(l.actual), difference: r3(l.actual - l.theoretical) }))
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
