+// Sales from the till. Each dish sold uses one portion of its recipe per
+// unit of `qty`; the ingredients are consumed with ref `sale:<ticket>`. A
+// ticket is recorded once, so importing it again changes nothing.
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** True when a ticket has already been recorded. */
+export function ticketRecorded(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient quantities used by selling `qty` of a dish (3 decimals). */
+export function saleUses(store, dishId, qty) {
+  const dish = getDish(store, dishId);
+  return scaled(getRecipe(store, dish.recipeId), qty);
+}
+
+/**
+ * Records one ticket: stores the sale and consumes its ingredients. Callers
+ * check stock first; `lines` are { dishId, qty, soldAt }.
+ */
+export function recordSale(store, ticket, lines) {
+  store.data.sales ??= [];
+  const sale = {
+    id: store.nextId("sale"),
+    ticket,
+    lines: lines.map((l) => ({ dishId: l.dishId, qty: l.qty, soldAt: l.soldAt, uses: saleUses(store, l.dishId, l.qty) })),
+  };
+  for (const line of sale.lines)
+    for (const u of line.uses) if (u.qty > 0) consume(store, u.itemId, u.qty, { at: line.soldAt, ref: `sale:${ticket}` });
+  store.data.sales.push(sale);
+  return sale;
+}
